$config = [
 'courses'=>['title'=>'Courses','table'=>'courses','roles'=>['Super Admin','Content Manager'],'fields'=>['department_id'=>['Department','department'],'name'=>['Course name','text',1],'level'=>['Level','enum',['Artisan','Certificate','Craft','Diploma','Other']],'duration'=>['Duration','text',1],'entry_requirements'=>['Entry requirements','textarea',1],'description'=>['Description','textarea',1],'modules'=>['Modules','textarea'],'careers'=>['Career opportunities','textarea'],'fees'=>['Fees','text'],'funding'=>['Funding information','textarea'],'image'=>['Course image','image'],'status'=>['Publication status','enum',['draft','published']],'featured'=>['Featured','bool']]],
 'departments'=>['title'=>'Departments','table'=>'departments','roles'=>['Super Admin','Content Manager'],'fields'=>['name'=>['Name','text',1],'description'=>['Description','textarea'],'status'=>['Status','enum',['active','inactive']]]],
 'news'=>['title'=>'News articles','table'=>'news','roles'=>['Super Admin','Content Manager'],'fields'=>['title'=>['Title','text',1],'slug'=>['Slug','text',1],'excerpt'=>['Excerpt','textarea'],'image'=>['Featured image','image'],'content'=>['Content','textarea',1],'author'=>['Author','text'],'category'=>['Category','text',1],'status'=>['Status','enum',['draft','published']],'published_at'=>['Publish date and time','datetime',1]]],
 'events'=>['title'=>'Events','table'=>'events','roles'=>['Super Admin','Content Manager'],'fields'=>['title'=>['Title','text',1],'event_date'=>['Date','date',1],'event_time'=>['Time','time'],'location'=>['Location','text'],'description'=>['Description','textarea',1],'image'=>['Event image','image']]],
 'downloads'=>['title'=>'Downloads','table'=>'downloads','roles'=>['Super Admin','Content Manager'],'fields'=>['title'=>['Title','text',1],'description'=>['Description','textarea'],'category'=>['Category','enum',['Admission','Fees','Brochures','Forms','Policies','Student documents','Other']],'file_path'=>['Resource file','pdf'],'is_public'=>['Public','bool']]],
 'gallery'=>['title'=>'Gallery','table'=>'gallery','roles'=>['Super Admin','Content Manager'],'fields'=>['title'=>['Image title','text',1],'category'=>['Category','text',1],'image_path'=>['Image file','image',1],'is_published'=>['Published','bool']]],
 'staff'=>['title'=>'Staff','table'=>'staff','roles'=>['Super Admin','Content Manager'],'fields'=>['name'=>['Name','text',1],'position'=>['Position','text',1],'department_id'=>['Department','department_optional'],'biography'=>['Biography','textarea'],'photo'=>['Photo','image'],'email'=>['Email','email'],'status'=>['Status','enum',['active','inactive']]]],
 'faqs'=>['title'=>'FAQs','table'=>'faqs','roles'=>['Super Admin','Content Manager'],'fields'=>['question'=>['Question','text',1],'answer'=>['Answer','textarea',1],'sort_order'=>['Sort order','number'],'is_published'=>['Published','bool']]],
 'facilities'=>['title'=>'Facilities','table'=>'facilities','roles'=>['Super Admin','Content Manager'],'fields'=>['name'=>['Name','text',1],'description'=>['Description','textarea',1],'image'=>['Image','image'],'sort_order'=>['Sort order','number'],'is_published'=>['Published','bool']]],
 'vacancies'=>['title'=>'Vacancies','table'=>'vacancies','roles'=>['Super Admin','Content Manager'],'fields'=>['title'=>['Job title','text',1],'department'=>['Department','text',1],'description'=>['Description','textarea',1],'requirements'=>['Requirements','textarea',1],'deadline'=>['Deadline','date',1],'file_path'=>['Job description file','pdf'],'instructions'=>['Application instructions','textarea',1],'status'=>['Status','enum',['draft','published','closed']]]],
];
if (!isset($config[$module])) { http_response_code(404); exit('Unknown management area.'); }
$settings=$config[$module];require_admin($settings['roles']);
$editing=null;$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;
if($editId){$st=db()->prepare('SELECT * FROM '.$settings['table'].' WHERE id=?');$st->execute([$editId]);$editing=$st->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'save');
 try{
  if($action==='delete'){$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:0;$st=db()->prepare('DELETE FROM '.$settings['table'].' WHERE id=?');$st->execute([$id]);flash('success','Record deleted.');}
  else{
    $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:0;$values=[];$errors=[];$existingRecord=[];
     if($id){$current=db()->prepare('SELECT * FROM '.$settings['table'].' WHERE id=?');$current->execute([$id]);$existingRecord=$current->fetch()?:[];if(!$existingRecord)throw new RuntimeException('Record not found.');}
   $departments=db()->query('SELECT id FROM departments')->fetchAll(PDO::FETCH_COLUMN);
   foreach($settings['fields'] as $key=>$field){$type=$field[1];$value=$_POST[$key]??'';
    if(in_array($type,['image','pdf'],true)){
    if(!empty($_FILES[$key]['name'])){$mimes=$type==='image'?['image/jpeg','image/png','image/webp']:['application/pdf'];$value=upload_file($_FILES[$key],$mimes,'content');}
    else{$value=(string)($existingRecord[$key]??'');}
    if(!empty($field[2])&&$value==='')$errors[]=$field[0].' is required.';
    }elseif($type==='department'||$type==='department_optional'){
     $value=(int)$value;if($type==='department_optional'&&$value===0)$value=null;if($value!==null&&!in_array($value,$departments))$errors[]='Choose a valid department.';
    }elseif($type==='enum'){
     if(!in_array((string)$value,$field[2],true))$errors[]='Choose a valid value for '.$field[0].'.';
    }elseif($type==='bool'){$value=isset($_POST[$key])?1:0;
    }elseif($type==='number'){$value=(int)$value;
    }else{$value=trim((string)$value);if($type==='datetime'&&$value!=='')$value=str_replace('T',' ',$value).':00';if(!empty($field[2])&&$value==='')$errors[]=$field[0].' is required.';if($type==='email'&&$value!==''&&!filter_var($value,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';}
    if($type==='image'||$type==='pdf'){$value=$value!==''?$value:null;}
    $values[$key]=$value;
   }
   if($module==='news'&&empty($values['published_at']))$values['published_at']=date('Y-m-d H:i:s');
   if(!$errors){
    if($id){$set=implode(',',array_map(fn($key)=>"`$key`=?",array_keys($values)));$values[]=$id;$st=db()->prepare('UPDATE '.$settings['table'].' SET '.$set.' WHERE id=?');$st->execute(array_values($values));}
    else{$cols=implode(',',array_map(fn($key)=>"`$key`",array_keys($values)));$marks=implode(',',array_fill(0,count($values),'?'));$st=db()->prepare('INSERT INTO '.$settings['table'].' ('.$cols.') VALUES ('.$marks.')');$st->execute(array_values($values));}
    flash('success','Record saved.');
   }else{flash('error',implode(' ',$errors));}
  }
 }catch(Throwable $error){flash('error','Could not save this record. Check required fields and existing relationships.');}
 redirect('admin/manage.php?type='.rawurlencode($module));
}
$rows=db()->query('SELECT * FROM '.$settings['table'].' ORDER BY id DESC LIMIT 100')->fetchAll();
if($editing&&isset($settings['fields'])){foreach($settings['fields'] as $key=>$field){if($field[1]==='datetime'&&!empty($editing[$key]))$editing[$key]=date('Y-m-d\TH:i',strtotime($editing[$key]));}}
$pageTitle=$settings['title'];include __DIR__.'/../includes/header.php';
$nav=['Dashboard'=>'dashboard.php','Applications'=>'applications.php','Students'=>'students.php','Courses'=>'courses.php','Departments'=>'departments.php','News'=>'news.php','Events'=>'events.php','Gallery'=>'gallery.php','Downloads'=>'downloads.php','Staff'=>'staff.php','Enquiries'=>'enquiries.php','FAQs'=>'faqs.php','Settings'=>'settings.php'];
?><section class="admin-shell"><aside class="admin-sidebar"><?php foreach($nav as $label=>$path):?><a href="<?= e(url('admin/'.$path)) ?>"><?= e($label) ?></a><?php endforeach;?></aside><div class="admin-content"><p class="eyebrow">Content management</p><h1><?= e($settings['title']) ?></h1><?php include __DIR__.'/../includes/alerts.php';?><form class="form-panel" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><h2><?= $editing?'Edit record':'Add record' ?></h2><div class="form-grid"><?php foreach($settings['fields'] as $key=>$field):$type=$field[1];$value=$editing[$key]??''; ?><div class="field <?= in_array($type,['textarea'],true)?'field-full':'' ?>"><label for="f_<?= e($key) ?>"><?= e($field[0]) ?><?= !empty($field[2])&&is_int($field[2])?' *':'' ?></label><?php if($type==='textarea'):?><textarea id="f_<?= e($key) ?>" name="<?= e($key) ?>" <?= !empty($field[2])?'required':'' ?>><?= e((string)$value) ?></textarea><?php elseif($type==='enum'):?><select id="f_<?= e($key) ?>" name="<?= e($key) ?>" required><?php foreach($field[2] as $option):?><option value="<?= e($option) ?>" <?= (string)$value===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach;?></select><?php elseif($type==='department'||$type==='department_optional'):$options=db()->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();?><select id="f_<?= e($key) ?>" name="<?= e($key) ?>" <?= $type==='department'?'required':'' ?>><?php if($type==='department_optional'):?><option value="0">None</option><?php endif;?><?php foreach($options as $option):?><option value="<?= (int)$option['id'] ?>" <?= (string)$value===(string)$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select><?php elseif($type==='bool'):?><input type="checkbox" id="f_<?= e($key) ?>" name="<?= e($key) ?>" value="1" <?= $value?'checked':'' ?>><?php elseif($type==='image'||$type==='pdf'):?><input type="hidden" name="<?= e($key) ?>_existing" value="<?= e((string)$value) ?>"><input id="f_<?= e($key) ?>" type="file" name="<?= e($key) ?>" accept="<?= $type==='image'?'image/jpeg,image/png,image/webp':'.pdf,application/pdf' ?>"><small>Maximum 5 MB<?= $value?' · Existing file retained if unchanged':'' ?></small><?php else:?><input id="f_<?= e($key) ?>" name="<?= e($key) ?>" type="<?= e(match($type){'email'=>'email','date'=>'date','time'=>'time','datetime'=>'datetime-local','number'=>'number',default=>'text'}) ?>" value="<?= e((string)$value) ?>" <?= !empty($field[2])&&is_int($field[2])?'required':'' ?>><?php endif;?></div><?php endforeach;?></div><div class="form-actions"><button class="button">Save record</button><?php if($editing):?><a class="button button-outline" href="<?= e(url('admin/manage.php?type='.$module)) ?>">Cancel</a><?php endif;?></div></form><h2>Current records <small>(latest 100)</small></h2><div class="table-wrap"><table><thead><tr><th>ID</th><?php foreach(array_slice(array_keys($settings['fields']),0,3) as $key):?><th><?= e($settings['fields'][$key][0]) ?></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?= (int)$row['id'] ?></td><?php foreach(array_slice(array_keys($settings['fields']),0,3) as $key):?><td><?= e(mb_strimwidth((string)($row[$key]??''),0,80,'…')) ?></td><?php endforeach;?><td><a class="text-link" href="<?= e(url('admin/manage.php?type='.$module.'&edit='.$row['id'])) ?>">Edit</a><form method="post" data-confirm="Delete this record?" style="display:inline"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="action" value="delete"><button class="text-link">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include __DIR__.'/../includes/footer.php';?>